package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;import com.mojang.math.Axis;
public final class Fl01Renderers{
 public static final class Aircraft extends EntityRenderer<Fl01Entity>{public Aircraft(EntityRendererProvider.Context c){super(c);shadowRadius=1.6f;}@Override public ResourceLocation getTextureLocation(Fl01Entity e){return ResourceLocation.tryParse("sbwdroneconfig:fl01/missile.png");}@Override public void render(Fl01Entity e,float yaw,float partial,PoseStack p,MultiBufferSource buffers,int light){p.pushPose();p.mulPose(Axis.YP.rotationDegrees(180-net.minecraft.util.Mth.rotLerp(partial,e.yRotO,e.getYRot())));p.mulPose(Axis.XP.rotationDegrees(-net.minecraft.util.Mth.lerp(partial,e.xRotO,e.getXRot())));Fl01Model.get(0).draw(0,p,buffers,light,OverlayTexture.NO_OVERLAY,0,e.pink(),false,true);p.popPose();}}
 public static final class Platform implements BlockEntityRenderer<Fl01PlatformBlockEntity>{public Platform(BlockEntityRendererProvider.Context c){}@Override public net.minecraft.world.phys.AABB getRenderBoundingBox(Fl01PlatformBlockEntity b){return b.getRenderBoundingBox();}@Override public boolean shouldRenderOffScreen(Fl01PlatformBlockEntity b){return true;}@Override public int getViewDistance(){return 256;}@Override public void render(Fl01PlatformBlockEntity b,float partial,PoseStack p,MultiBufferSource buffers,int light,int overlay){p.pushPose();p.translate(.5,0,.5);p.mulPose(Axis.YP.rotationDegrees(180-b.facing().toYRot()));Fl01Model.get(1).draw(1,p,buffers,light,overlay,b.animation(partial),false,false,true);var loaded=b.preview();if(!loaded.isEmpty()){p.pushPose();double t=b.previewTime(partial);p.translate(0,1.3,3.5);p.mulPose(Axis.XP.rotationDegrees((float)Fl01Geometry.rail(t)));p.translate(0,-1.3,-3.5);p.translate(0,2.66,-.8);double elapsed=b.handoffTravel(partial);p.translate(0,0,-(.65*elapsed+.0175*elapsed*(elapsed+1)));Fl01Model.get(0).draw(0,p,buffers,light,overlay,0,Fl01Item.pink(loaded),false,true);p.popPose();}p.popPose();}}
}
